package com.restro.restaurantservice.web.controller;
import com.restro.restaurantservice.service.WeekOffService; import com.restro.restaurantservice.web.dto.WeekOffRequest; import com.restro.restaurantservice.web.dto.WeekOffResponse; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/attendance/week-offs") @PreAuthorize("hasAnyRole('OWNER','MANAGER')") public class WeekOffController { private final WeekOffService service; public WeekOffController(WeekOffService service){this.service=service;} @GetMapping("/{staffId}") public WeekOffResponse get(@PathVariable("staffId") Long staffId){return service.get(staffId);}@PutMapping public WeekOffResponse save(@Valid @RequestBody WeekOffRequest request){return service.save(request);} }
